// Tolerant pickup: any upstream node may have failed; never throw.
function safeFirst(name) {
  try { return $(name).first().json; } catch (e) { return null; }
}
const health = safeFirst('Check System Health') || {};
const stats = safeFirst('Fetch Pipeline Stats') || {};
const strategies = safeFirst('Check Strategy Pipeline') || {};

const s = stats.data || stats || {};
const strats = strategies.data || strategies || [];
const stratList = Array.isArray(strats) ? strats : [];

const healthStatus = health.status || health.error || 'unknown';
const activeCount = stratList.filter(s => s.lifecycleState === 'ACTIVE' || s.lifecycleState === 'PAPER').length;
const testingCount = stratList.filter(s => s.lifecycleState === 'TESTING').length;
const decayCount = stratList.filter(s => s.lifecycleState === 'DECLINING' || s.decaying).length;

const lines = [
  'System Health: ' + healthStatus,
  'Total Strategies: ' + stratList.length,
  'Active/Paper: ' + activeCount,
  'Testing: ' + testingCount,
  'Declining: ' + decayCount,
  'Ideas sourced: ' + (s.totalIdeas ?? s.ideas ?? 'N/A'),
  'Backtests run: ' + (s.totalBacktests ?? s.backtests ?? 'N/A'),
  'Pass rate: ' + (s.passRate ?? 'N/A')
];

const severity = healthStatus !== 'ok' ? 'warning' : 'info';
return [{ json: { event: 'orchestration:daily-summary', data: { title: 'Daily Pipeline Summary (5 AM ET)', severity, body: lines.join('\n'), healthStatus, strategyCount: stratList.length, activeCount, testingCount, decayCount } } }];

